insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('kum-hea-do-und-puudl-do-moi-eine-damit-i-siich-ob-s-passt', 'Kum hea do und puudl do moi eine, damit I siich, ob''s passt!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Komm her da und pudle da mal rein, damit ich sehe, ob es passt!', '[{"kategorie": "wörtlich", "text": "\"Komm her da und schlüpf da mal rein, damit ich sehe, ob es passt!\"  2. Komm her und probier das mal an, damit ich sehen kann, ob es passt!  3. Komm mal her und hüpf da rein, damit ich sehe, wie’s sitzt!"}]'::jsonb, ''),
  ('si-einepuudln-in-de-pania', 'si einepuudln in de Pania', '', '', '', 'Wiener Sprüche, die sitzen!', 'sich reinpudeln in die Panier', '[{"kategorie": "wörtlich", "text": "\"sich ins Gewand schmeißen\""}, {"kategorie": "", "text": "\"ins Gewand hineinschlüpfen\""}, {"kategorie": "", "text": "\"sich ins Gewand werfen\""}]'::jsonb, ''),
  ('bevua-i-ind-kiachn-gee-puudl-i-mi-eine-in-mei-aansapania', 'Bevua I ind Kiachn gee, puudl I mi eine in mei Aansapania!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bevor ich in die Kirche geh, pudle ich mich rein in meine Einserpanier!', '[{"kategorie": "wörtlich", "text": "\"Bevor ich in die Kirche geh, zwäng ich mich noch rein in meinen Sonntagsanzug!\"  2. Bevor ich zum Gottesdienst geh, schlüpf ich vorher noch in meinen Sonntagsanzug!  3. Bevor''s zur Kirche geht, werf ich mich noch in meinen besten Zwirn!"}]'::jsonb, 'si einepuudln in de Pania'),
  ('si-eineraunzn', 'si eineraunzn', '', '', '', 'Grundwortschatz Wienerisch', 'sich eineraunzen', '[{"kategorie": "wörtlich", "text": "\"sich reinraunzen\" (Kompositum aus dem abtrennbaren Präfix [[eine]]=\"hinein\" und [[raunzen]]=\"jammern\")"}, {"kategorie": "allg.", "text": "sich ranschleimen, sich reinwanzen, sich einschleimen, sich einschleichen, [[si]] eiweimpaln"}]'::jsonb, ''),
  ('kaana-hod-eam-wiaklich-zruck-woin-owa-ea-hod-si-hoid-wiida-einegraunzd', 'Kaana hod eam wiaklich zruck woin - owa ea hod si hoid wiida einegraunzd!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Keiner hat ihn wirklich zurückgewollt - aber er hat sich halt wieder reingeraunzt!', '[{"kategorie": "wörtlich", "text": "\"Keiner wollte ihn wirklich zurück - aber er hat sich halt wieder reingewanzt!\"  2. Keiner wollte ihn wirklich zurückhaben - aber er hat sich halt wieder rangeschleimt!  3. Niemand wollte, dass er wieder zurückkommt - aber er hat sich halt wieder irgendwie eingeschlichen!"}]'::jsonb, ''),
  ('ka-rueckgrat-owa-a-maasta-im-oaschkraeun-a-eineraunza-hoid', 'Ka Rückgrat, owa a Maasta im Oaschkräun - a Eineraunza hoid!', '', '', '', 'Wiener Gaunersprache', 'Kein Rückgrat, aber ein Meister im Arschkriechen - ein Eineraunzer halt!', '[{"kategorie": "wörtlich", "text": "\"Kein Rückgrat, aber ein Meister im Arschkriechen - ein echter Schleimbeutel halt!\"  2. Keine Prinzipien, aber ein Meister des Reinwanzens - ein Arschgesicht mit Kriechfaktor 10!  3. Ein Opportunist und Reinwanzer par excellence - ein Schleimbolzen halt!"}]'::jsonb, ''),
  ('waunn-du-auf-so-an-eiweimpla-einefoist-tuast-ma-laad', 'Waunn du auf so an Eiweimpla einefoist, tuast ma laad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du auf einen solchen Einweimpler reinfällst, tust du mir leid!', '[{"kategorie": "wörtlich", "text": "\"Wenn du auf so einen honigsüßen Schmeichler reinfällst, tust du mir leid!\"  2. Wenn du dich von so einem zuckersüßen Schleimer einwickeln lässt, bist du selber schuld!  3. Wenn du auf so einen Schleimbeutel reinfällst, kann ich dir auch nicht helfen!"}]'::jsonb, ''),
  ('wem-wos-einereim', 'wem wos einereim', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem etwas reinreiben', '[{"kategorie": "wörtlich", "text": "\"jemandem etwas unter die Nase reiben\""}, {"kategorie": "", "text": "jemandem etwas reindrücken"}, {"kategorie": "", "text": "jemandem etwas aufs Brot schmieren"}, {"kategorie": "", "text": "jemandem etwas unverhohlen klarmachen"}]'::jsonb, ''),
  ('wueuesd-ma-jetzt-leichd-einereim-dass-i-aun-oim-schuid-bin', 'Wüüsd ma jetzt leichd einereim, dass I aun oim schuid bin?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Willst du mir jetzt vielleicht reinreiben, dass ich an allem schuld bin?', '[{"kategorie": "wörtlich", "text": "\"Willst du mir jetzt vielleicht unter die Nase reiben, dass ich an allem schuld bin?\"  2. Versuchst du mir jetzt etwa reinzudrücken, dass ich die Ursache allen Übels bin?  3. Willst du mir damit etwa aufs Brot schmieren, dass das alles meine Schuld ist?"}]'::jsonb, 'wem wos einereim'),
  ('wem-wos-einesoong', 'wem wos einesoong', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem was reinsagen', '[{"kategorie": "wörtlich", "text": "\"jemandem etwas direkt ins Gesicht sagen\""}, {"kategorie": "", "text": "jemandem gegenüber etwas offen aussprechen"}, {"kategorie": "", "text": "jemandem etwas klipp und klar zu verstehen geben"}, {"kategorie": "", "text": "jemandem reinen Wein einschenken"}, {"kategorie": "", "text": "jemandem etwas unverhohlen klarmachen"}]'::jsonb, 'Ma muass eams einesoong, dass ma de nächste Saison oone eam planan!'),
  ('ma-muass-eams-einesoong-dass-ma-de-naechste-saison-oone-eam-planan', 'Ma muass eams einesoong, dass ma de nächste Saison oone eam planan!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Man muss es ihm reinsagen, dass wir die nächste Saison ohne ihn planen!', '[{"kategorie": "wörtlich", "text": "\"Man muss es ihm direkt ins Gesicht sagen, dass wir die nächste Saison ohne ihn planen!\"  2. Wir müssen ihm reinen Wein einschenken – er ist nächstes Jahr nicht mehr dabei!  3. Man muss ihm klipp und klar zu verstehen geben,  dass wir die nächste Saison ohne ihn planen!"}]'::jsonb, 'wem wos einesoong'),
  ('vakeat-einescheibm', 'vakeat einescheibm', '', '', '', 'Wiener Sprüche, die sitzen!', 'verkehrt eineschieben', '[{"kategorie": "wörtlich", "text": "\"rückwärts reinschieben\""}, {"kategorie": "", "text": "rückwärts einparken"}, {"kategorie": "", "text": "mit dem Auto rückwärts in eine Parklücke fahren"}]'::jsonb, ''),
  ('min-auto-vakead-einescheibm-hods-bis-heit-ned-gscheid-gleant', 'Min Auto vakead einescheibm hods bis heit ned gscheid gleant!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mit dem Auto rückwärts reinschieben hat sie bis heute nicht gescheit gelernt!', '[{"kategorie": "wörtlich", "text": "\"Rückwärts einparken hat sie bis heute nicht richtig gelernt!\"  2. Das rückwärtige Einparken fällt ihr immer noch schwer!  3. Rückwärts einparken ist bis heute nicht ihre Stärke!"}]'::jsonb, 'vakeat einescheibm'),
  ('scheib-eine', 'Scheib eine!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Schieb eine!', '[{"kategorie": "wörtlich", "text": "\"Schieb rein!\"  2. \"Schlag ein!\" (in die ausgestreckte Hand)"}, {"kategorie": "", "text": "Hand drauf!  4. Gib mir fünf!"}]'::jsonb, ''),
  ('kenntast-ma-schnoe-in-den-pulli-do-eineschliafn-damit-i-siich-oba-passd', 'Kenntast ma schnö in den Pulli do eineschliafn - damit I siich, oba passd!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Könntest du mir schnell in den Pulli da reinschliefen - damit ich sehe, ob er passt!', '[{"kategorie": "wörtlich", "text": "\"Könntest du mir schnell in den Pulli da reinschlüpfen - damit ich sehe, ob er passt!\"  2. Schlüpf mal kurz in den Pulli - ich will sehen, ob die Größe passt!  3. Schlüpf mal rein in den Pulli – ich bin gespannt, wie der dir steht!"}]'::jsonb, ''),
  ('wem-eineschliafn', 'wem eineschliafn', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem reinschliefen', '[{"kategorie": "wörtlich", "text": "\"jemandem reinschlüpfen\" (Kompositum aus [[eine]]=\"hinein\" und [[schliafn]]=\"schlüpfen\")"}, {"kategorie": "allg.", "text": "\"jemandem unter die Haut schlüpfen\", \"sich bei jemandem einschleimen\", \"jemandem von hinten reinkriechen\", [[si bei wem eiweimpaln]], [[wem in Oasch kräun]]"}]'::jsonb, ''),
  ('wea-dera-eineschliafd-is-im-oasch-dahaam', 'Wea dera eineschliafd, is im Oasch dahaam!', '', '', '', 'Wiener Gaunersprache', 'Wer ihr reinschlieft, ist im Arsch daheim!', '[{"kategorie": "wörtlich", "text": "\"Wer sich bei ihr einschleimt, ist so gut wie erledigt!\"  2. \"Wer dieser Frau von hinten reinkriecht, hat nichts mehr zu melden!\"  3. \"Wer bei dieser Frau kriecht, fliegt – und zwar raus!\""}]'::jsonb, 'wem eineschliafn'),
  ('ea-puudld-seit-schdundn-aun-dem-oidn-mopal-umanaund-oone-eafoig', 'Ea puudld seit Schdundn aun dem oidn Mopal umanaund - oone Eafoig!', '', '', '', 'Wiener Mechaniker-Slang', 'Er pudelt seit Stunden an dem alten Moped herum - ohne Erfolg!', '[{"kategorie": "wörtlich", "text": "\"Er bastelt seit Stunden an dem alten Moped herum - ohne Erfolg!\"  2. Er schraubt seit Stunden an dem alten Moped rum – vergeblich!  3. Er plagt sich seit Stunden mit dem alten Moped rum – bisher erfolglos!"}]'::jsonb, ''),
  ('noch-jedn-reeng-puudln-de-antn-im-gatsch', 'Noch jedn Reeng puudln de Antn im Gatsch!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Nach jedem Regen pudeln die Enten im Gatsch!', '[{"kategorie": "wörtlich", "text": "\"Nach jedem Regen plantschen die Enten im Matsch!\"  2. Nach jedem Schauer tanzen die Enten fröhlich durch den Schlamm!  3. Die Enten feiern jeden Regenguss mit einem ausgelassenen Schlammbad!"}]'::jsonb, ''),
  ('des-papial-is-beim-fensta-aussegseegld', 'Des Papial is beim Fensta aussegseegld!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Das Papierl ist beim Fenster rausgesegelt!', '[{"kategorie": "wörtlich", "text": "\"Das Stück Papier ist beim Fenster rausgesegelt!\"  2. Das Zettelchen ist aus dem Fenster geflattert!  3. Das Blatt segelte beim Fenster raus, als hätte es genug vom Schreibtischleben!"}]'::jsonb, ''),
  ('si-is-einegseegld-kumma-ois-daed-des-buero-ia-allaa-ghean', 'Si is einegseegld kumma, ois däd des Büro ia allaa ghean!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie ist reingesegelt gekommen, als täte das Büro ihr alleine gehören!', '[{"kategorie": "wörtlich", "text": "\"Sie kam reingesegelt, als würde ihr der Laden allein gehören!\"  2. Sie ist ins Büro reingeschneit, als wär sie die Chefin höchstpersönlich!  3. Sie ist hineingerauscht, als gehörte ihr der ganze Betrieb alleine!"}]'::jsonb, ''),
  ('i-bin-voi-in-de-abo-foin-einegeseegld', 'I bin voi in de Abo-Foin einegeseegld!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich bin voll in die Abo-Falle reingesegelt!', '[{"kategorie": "wörtlich", "text": "\"Ich bin voll in die Abo-Falle reingetappt!\"  2. Ich bin glatt auf den Abo-Schmäh reingefallen!  3. Ich hab mich von dem kostenlosen Testabo schön reinlegen lassen!"}]'::jsonb, ''),
  ('waunnsd-so-in-a-kuavn-eineschdichst-iwaschlogsd-di-fia-noamal', 'Waunnsd so in a Kuavn eineschdichst, iwaschlogsd di fia noamal!', '', '', '', 'Wiener Mechaniker-Slang', 'Wenn du so in eine Kurve reinstichst, überschlägst du dich für normal!', '[{"kategorie": "wörtlich", "text": "\"Wenn du so in eine Kurve reinballerst, fliegst du normalerweise sofort ab!\"  2. Wenn du da so reinstichst, liegst du für gewöhnlich im Graben, bevor du gucken kannst!  3. Wenn du so in die Kurve einfährst, verlierst du im Regelfall sofort die Bodenhaftung!"}]'::jsonb, ''),
  ('schdrick-da-s-hemad-eine-ind-hosn-schaud-scho-wiida-ollas-aussa', 'Schdrick da s''Hemad eine ind Hosn - schaud scho wiida ollas aussa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Strick dir das Hemd rein in die Hose - es schaut schon wieder alles raus!', '[{"kategorie": "wörtlich", "text": "\"Steck dir das Hemd in Hose rein - es schaut schon wieder alles raus!\"  2. Zupf dein Hemd mal rein - es hängt schon wieder alles raus!  3. Stopf dir das Hemd rein – hängt ja schon wieder alles raus!"}]'::jsonb, ''),
  ('schdrick-da-s-hemad-eini-ind-hosn-schaud-scho-wiida-ollas-aussa', 'Schdrick da s''Hemad eini ind Hosn - schaud scho wiida ollas aussa!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Strick dir das Hemd rein in die Hose - es schaut schon wieder alles raus!', '[{"kategorie": "wörtlich", "text": "\"Steck dir das Hemd in Hose rein - es schaut schon wieder alles raus!\"  2. Zupf dein Hemd mal rein - es hängt schon wieder alles raus!  3. Stopf dir das Hemd rein – hängt ja schon wieder alles raus!"}]'::jsonb, ''),
  ('heast-renn-ned-oiwaeu-durch-de-blumanbeetln-du-zadoodscht-ma-jo-de-gaunzn-bleamaln', 'Heast, renn ned oiwäu durch de Blumanbeetln, du zadoodscht ma jo de gaunzn Bleamaln', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör mal! Renn nicht alleweil durch die Blumenbeetchen, du zertrittst mir ja die ganzen Blumen!', '[{"kategorie": "wörtlich", "text": "\"Hör mal! Laufe nicht alleweil durch die Blumenbeetchen, du zertrittst mir ja sämtliche Blumen!\"  2. \"Pass auf! Tritt nicht ständig durch die Blumenbeete, du trampelst mir ja alle Blumen nieder!  3. \"Hey, bitte nicht immer durch die Blumenbeete laufen – du trittst mir sonst alles platt!\""}]'::jsonb, ''),
  ('dea-is-in-gooli-voi-ind-eia-einedreedn', 'Dea is in Gooli voi ind Eia einedreedn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der ist dem Goalie voll in die Eier reingetreten!', '[{"kategorie": "wörtlich", "text": "\"Der hat den Keeper voll zwischen die Beine getreten!\"  2. Der ist dem Tormann brutal in die Kronjuwelen gestiegen!  3. Der hat dem Torwart mit einem Tritt ins Gemächt die Nüsse geknackt!"}]'::jsonb, ''),
  ('vueue-fiaman-fian-luxuswoan-iwan-wiina-hoofn-ei-und-vatreibns-daunn-in-gaunz-europa', 'Vüü Fiaman fian Luxuswoan iwan Wiina Hoofn ei und vatreibns daunn in gaunz Europa!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Viele Firmen führen Luxuswaren über den Wiener Hafen ein und vertreiben sie dann in ganz Europa!', '[{"kategorie": "wörtlich", "text": "\"Mehrere Unternehmen führen ihre Luxuswaren über den Wiener Hafen ein und vertreiben sie dann in ganz Europa!\"  2. Zahlreiche Firmen importieren hochwertige Waren über den Wiener Hafen und liefern sie dann in ganz Europa aus!  3. Luxusgüter gelangen über den Hafen Wien in den europäischen Handel – eingeführt von zahlreichen spezialisierten Unternehmen"}]'::jsonb, ''),
  ('den-jungschbund-muassd-in-de-materii-easchd-amoi-eifian', 'Den Jungschbund muassd in de Materii easchd amoi eifian!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Den Jungspund musst du in die Materie erst einmal einführen!', '[{"kategorie": "wörtlich", "text": "\"Den jungen Kollegen musst du in die Materie erst einmal einführen!\"  2. Dem Neuling musst du erst mal die Grundlagen beibringen!  3. Den Frischling müssen wir erst noch einarbeiten!"}]'::jsonb, ''),
  ('eam-eifian', 'eam eifian', '', '', '', 'Wiener Sprüche, die sitzen!', 'ihn einführen', '[{"kategorie": "wörtlich", "text": "\"sein bestes Stück einführen\""}, {"kategorie": "", "text": "seinen Penis einführen, sexuellen Verkehr haben, [[pudern]], [[schnackseln]]"}]'::jsonb, 'Bevua I eam bei dera eifia, hoi I man liawa sööwa owe!'),
  ('bevua-i-eam-bei-dera-eifia-hoi-i-man-liawa-soeoewa-owe', 'Bevua I eam bei dera eifia, hoi I man liawa sööwa owe!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Bevor ich ihn bei der einführe, hole ich ihn mir lieber selber runter!', '[{"kategorie": "wörtlich", "text": "\"Bevor ich mein bestes Stück bei dieser Tussi einführe, mach ich''s mir lieber selbst!\"  2. Bevor ich mir den Stress mit diesem Luder da antue, mach ich’s mir lieber selbst!  3. Bevor ich mein bestes Stück in diese Tussi reinstecke, hol ich mir lieber selbst einen runter!"}]'::jsonb, 'eam eifian'),
  ('a-eigwoschans-politisches-uagestein', 'a eigwoschans, politisches Uagestein', '', '', '', '', 'ein eingewaschenes, politisches Urgestein', '[{"kategorie": "", "text": "ein waschechtes politisches Urgestein"}]'::jsonb, ''),
  ('si-bei-wem-eihaun', 'si bei wem eihaun', '', '', '', '', 'sich bei jemandem reinhauen', '[{"kategorie": "", "text": "sich bei jemandem einschmeicheln"}, {"kategorie": "", "text": "jemandem nach dem Mund reden, sich lieb Kind machen"}, {"kategorie": "", "text": "jemanden umschmeicheln, umgarnen"}]'::jsonb, ''),
  ('des-haut-ma-de-augn-ei', 'Des haut ma de Augn ei!', '', '', '', '', 'Das haut mir die Augen ein!', '[{"kategorie": "", "text": "Dieser Anblick versetzt mich in basses Erstaunen!  2. Das haut ich um!  3. Das ist beeindruckend!"}]'::jsonb, ''),
  ('i-loss-mi-sicha-ned-eikochn', 'I loss mi sicha ned eikochn!', '', '', '', '', 'Ich lasse mich sicher nicht einkochen', '[{"kategorie": "", "text": "Ich lasse mich sicher nicht rumkriegen!  2. Ich lasse mich sicher nicht reinlegen!"}]'::jsonb, ''),
  ('wem-ane-eischenkn', 'wem ane eischenkn', '', '', '', '', 'jemandem eine einschenken', '[{"kategorie": "", "text": "jemandem eine Ohrfeige verpassen, jemandem eine [[Watschen]] geben"}, {"kategorie": "", "text": "jemanden [[abwatschen]], [[abflaschen]]"}, {"kategorie": "", "text": "jemandem eine [[antauchen]], [[auflegen]], [[umhängen]]"}]'::jsonb, ''),
  ('si-auf-wem-eischiassn', 'si auf wem eischiassn', '', '', '', '', 'sich auf jemanden einschießen', '[{"kategorie": "", "text": "jemanden ins Visier nehmen"}, {"kategorie": "", "text": "jemanden (mit Worten oder Gedanken) zum wiederholten Angriffsziel machen"}]'::jsonb, ''),
  ('si-eischuastan', 'si eischuastan', '', '', '', '', 'sich einschustern', '[{"kategorie": "", "text": "sich einarbeiten, sich einschulen"}, {"kategorie": "", "text": "sich bei einem neuen Sexualpartner \"einreiten\""}]'::jsonb, ''),
  ('si-eischbritzn', 'si eischbritzn', '', '', '', '', 'sich einspritzen', '[{"kategorie": "", "text": "sich einen Schwips antrinken, sich ansäuseln"}, {"kategorie": "", "text": "sich einen leichten Rausch antrinken, [[sich]] eintrankeln, [[schwassn]]"}]'::jsonb, ''),
  ('kaana-waass-warum-de-briaftaum-imma-in-haamischn-schlog-zruckfliang', 'Kaana waass, warum de Briaftaum imma in haamischn Schlog zruckfliang!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Keiner weiß, warum die Brieftauben immer in den heimischen Schlag zurückfliegen!', '[{"kategorie": "wörtlich", "text": "\"Niemand weiß, warum Brieftauben stets in ihren Heimatschlag zurückkehren!\"  2. Es ist bis heute unklar, weshalb Brieftauben immer den Weg nach Hause finden!  3. Bis heute ist es ein Rätsel, wie Brieftauben ihr Zuhause so sicher wiederfinden!"}]'::jsonb, ''),
  ('moch-a-briaftaum-daunn-host-wiida-a-bissl-goeoed-im-sackl', 'Moch a Briaftaum, daunn host wiida a bissl Gööd im Sackl!', '', '', '', 'Wiener Gaunersprache', 'Mach eine Brieftaube, dann hast du wieder ein bisschen Geld im Sack!', '[{"kategorie": "wörtlich", "text": "\"Mach einen Geldbotenüberfall, dann hast du wieder ein bisschen Geld im Sackerl!\"  2. Überfall einen Geldboten, dann bist du finanziell wieder eine Zeitlang flüssig!  3. Raub den Briefträger aus, dann hast du wieder ein bisschen Bares im Sackerl!"}]'::jsonb, ''),
  ('waunnst-so-augflaschld-bist-wia-dea-do-findst-nimma-allaanich-haam', 'Waunnst so augflaschld bist wia dea do, findst nimma allaanich haam!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn du so angeflaschelt bist wie der da, findest du nicht mehr alleine heim!', '[{"kategorie": "wörtlich", "text": "\"Wenn du so angetrunken bist wie der Typ da, findest du den Nachhauseweg nicht mehr alleine!\"  2. Wenn du so betrunken bist wie der da, kommst du alleine nicht mehr nach Hause!  3. Wenn du so dicht bist wie der, brauchst du einen Abschleppdienst, der dich nach Hause bringt! (aishe auch [[augflaschld]])"}]'::jsonb, ''),
  ('auflaschln-tua-i-mi-imma-daunn-waunn-mei-schwiigamuada-zu-besuch-is', 'Auflaschln tua I mi imma daunn, waunn mei Schwiigamuada zu Besuch is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Anflascheln tu ich mich immer dann, wenn meine Schwiegermutter zu Besuch ist!', '[{"kategorie": "wörtlich", "text": "\"Ich trinke mir immer dann einen an, wenn meine Schwiegermutter zu Besuch ist!\"  2. Ich greife immer dann zur Flasche, wenn meine Schwiegrmutter kommt!  3. Wenn meine Schwiegermutter vorbeischaut, trinke ich mir vorher Mut an!"}]'::jsonb, ''),
  ('si-auschdraan', 'si auschdraan', '', '', '', '', 'sich anstreuen', '[{"kategorie": "", "text": "sich einen Schwips antrinken, sich ansäuseln"}, {"kategorie": "", "text": "sich einen leichten Rausch antrinken, [[sich]] eintrankeln, [[schwassn]]"}]'::jsonb, ''),
