  ('de-fliagl-ausbraatn', 'de Fliagl ausbraatn', '', '', '', '', 'die Flügel ausbreiten', '[{"kategorie": "", "text": "davonfliegen, fliehen, sich davonmachen"}, {"kategorie": "", "text": "den Dienst quittieren, kündigen"}]'::jsonb, ''),
  ('bei-dia-kriagt-ollas-fliagln', 'Bei dia kriagt ollas Fliagln!', '', '', '', '', 'Bei dir kriegt alles Flügel!', '[{"kategorie": "", "text": "Bei dir verschwindet alles!  2. Du lässt alles verkommen!  3. Bei dir löst sich alles in Luft auf!  4. Du verschlampst alles!"}]'::jsonb, ''),
  ('gegn-den-waadlbeissa-schbueued-kaana-gean-dea-vafoigd-di-bis-ind-kabin', 'Gegn den Waadlbeissa schbüüd kaana gean - dea vafoigd di bis ind Kabin!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Gegen diesen Wadlbeißer spielt keiner gern – der verfolgt dich bis in die Kabine!', '[{"kategorie": "wörtlich", "text": "\"Gegen diesen Manndecker spielt keiner gern - der verfolgt dich bis in die Umkleidekabine!\"  2. Gegen diesen Defensiv-Terrier spielt niemand gern - der atmet dir schon im Spielertunnel ins Genick!\"  3. Gegen diese [[Klettn]] spielt niemand gern - der klebt an dir wie Kaugummi im Stutzen!"}]'::jsonb, ''),
