  ('si-de-fiass-in-bauch-schdee', 'si de Fiass in Bauch schdee', '', '', '', '', 'sich die Füße in den Bauch stehen', '[{"kategorie": "wörtlich", "text": "\"sich die Beine in den Bauch stehen\" (sehr lange herumstehen und warten müssen, bis einem die Beine bis hinauf in den Bauch schmerzen)"}, {"kategorie": "", "text": "sich die Fersen wundstehen"}, {"kategorie": "", "text": "Ewigkeiten warten müssen"}]'::jsonb, ''),
  ('in-heagood-de-fiass-oschleckn', 'in Heagood de Fiaß oschleckn', '', '', '', '', 'dem Herrgott die Füße abschlecken', '[{"kategorie": "scherzhaft für", "text": "\"heiliger als der Papst sein\""}, {"kategorie": "", "text": "\"frommer als fromm sein\""}, {"kategorie": "", "text": "übertrieben gottesfürchtig sein"}]'::jsonb, ''),
  ('in-heagood-de-fiass-obeissn', 'in Heagood de Fiaß obeissn', '', '', '', '', 'dem Herrgott die Füße abbeißen', '[{"kategorie": "scherzhaft für", "text": "\"heiliger als der Papst sein\""}, {"kategorie": "", "text": "\"frommer als fromm sein\""}, {"kategorie": "", "text": "übertrieben gottesfürchtig sein"}]'::jsonb, ''),
  ('in-rekrutn-hod-da-owafoeoedwaeaewae-mit-da-fuchtl-zua-uadnung-gwiisn', 'In Rekrutn hod da Owaföödwääwä mit da Fuchtl zua Uadnung gwiisn!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Den Rekruten hat der Oberfeldwebel mit der Fuchtel zur Ordnung gewiesen!', '[{"kategorie": "wörtlich", "text": "\"Der Rekrut wurde vom Oberfeldwebel mit der Fuchtel zur Ordnung gewiesen!\"  2. \"Der Wehrmann wurde vom Oberfeldwebel mit einem Zuchtdegen diszipliniert!\"  3. Mehrere Hiebe mit dem Drilldegen des Oberfeldwebels sollten den Rekruten zur Ordnung anhalten!"}]'::jsonb, ''),
  ('soboid-de-fuchtl-aufaungd-zum-reedn-kriagsd-schaeaedlwaeae', 'Soboid de Fuchtl aufaungd zum Reedn, kriagsd Schäädlwää!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sobald die Fuchtel anfängt zu reden, kriegst du Schädelweh!', '[{"kategorie": "wörtlich", "text": "\"Sobald die Fuchtel anfängt zu reden, kriegt man Kopfschmerzen!\"  2. \"Sobald diese wild herumfuchtelnde Nervensäge zu reden beginnt, kriegt man Kopfweh!\"  3. \"Sobald diese Fuchtel den Mund aufmacht, fangen die Kopfschmerzen an!\""}]'::jsonb, ''),
  ('da-schaani-hod-a-echte-fuchtl-dahaam-de-ziagd-eam-es-foeoe-iwad-uan-waunna-z-schbood-haamkummd', 'Da Schaani hod a echte Fuchtl dahaam - de ziagd eam es Föö iwad Uan, waunna z''schbood haamkummd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Schani hat ''ne echte Fuchtel daheim - die zieht ihm das Fell über die Ohren, wenn er zu spät heimkommt!', '[{"kategorie": "wörtlich", "text": "\"Der Schani hat daheim ’ne Furie sitzen - die macht kurzen Prozess, wenn er spät auftaucht!\"  2. \"Beim Schani herrscht daheim ein Drachen von einem Weib – zu spät kommen ist Selbstmord!\"  3. \"Der Schani lebt unter der Fuchtel eines herrischen Weibs - wehe, er kommt erst nach Zapfenstreich heim!\""}]'::jsonb, ''),
  ('unta-da-fuchtl-von-wem-schdee', 'unta da Fuchtl von wem schdee', '', '', '', 'Wiener Sprüche, die sitzen!', 'unter jemandes Fuchtel stehen', '[{"kategorie": "wörtlich", "text": "\"unter der Kontrolle von jemandem stehen\""}, {"kategorie": "", "text": "\"unter jemandes strengem Kommando stehen\""}, {"kategorie": "allg.", "text": "von jemandem beherrscht werden, unter jemandes Pantoffel stehen, jemandem hilflos ausgeliefert sein"}]'::jsonb, 'Seita gheirat hod, schdeeda unta da Fuchtl von seine Oidn!'),
  ('seita-gheirat-hod-schdeeda-unta-da-fuchtl-von-seine-oidn', 'Seita gheirat hod, schdeeda unta da Fuchtl von seine Oidn!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Seit er geheiratet hat, steht er unter der Fuchtel von seiner Alten!', '[{"kategorie": "wörtlich", "text": "\"Seit er ihr das Jawort gegeben hat, steht er unter dem strengen Kommando seiner Frau!\"  2. \"Seit der Hochzeit tanzt er nur noch nach der Pfeife seiner Alten!\"  3. \"Seit er verheiratet ist, hat er daheim nichts mehr zu melden!\""}]'::jsonb, 'unta da Fuchtl von wem schdee'),
  ('de-leit-woan-mea-ois-fuchtig-wia-da-schiri-an-oeoefa-pfiffn-hod', 'De Leit woan mea ois fuchtig, wia da Schiri an Ööfa pfiffn hod!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Die Leute waren mehr als fuchtig, wie der Schiri einen Elfer gepfiffen hat!', '[{"kategorie": "wörtlich", "text": "\"Die Leute waren mehr als aufgebracht, als der Schiedsrichter einen Elfer gepfiffen hat!\"  2. \"Die Leute sind komplett ausgerastet, als der Schiri auf den Punkt gezeigt hat!\"  3. \"Der Elferpfiff hat das Stadion angezündet!\""}]'::jsonb, ''),
  ('fuchtig-wean', 'fuchtig wean', '', '', '', 'Wiener Sprüche, die sitzen!', 'fuchtig werden', '[{"kategorie": "wörtlich", "text": "\"in Zorn geraten\" (vom mittelhochdeutschen \"vorhtic\"=\"fuchtig\")"}, {"kategorie": "fig.", "text": "wütend werden, sich aufregen, aus der Haut fahren, an die Decke gehen"}]'::jsonb, 'Waunn I sowos hea, weari fuchtig!'),
  ('waunn-i-sowos-hea-weari-fuchtig', 'Waunn I sowos hea, weari fuchtig!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn ich so etwas höre, werde ich fuchtig!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich so etwas höre, werde ich wütend!\"  2. \"Wenn ich so etwas höre, gehe ich an die Decke!\"  3. \"Wenn ich so etwas höre, raste ich aus!"}]'::jsonb, 'fuchtig wean'),
  ('dea-wichsa-hod-sofuat-min-messa-gfuchtld-ois-warada-wea', 'Dea Wichsa hod sofuat min Messa gfuchtld, ois warada wea!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Wichser hat sofort mit dem Messer gefuchtelt, als wäre er wer!', '[{"kategorie": "wörtlich", "text": "\"Der Penner hat gleich das Messer geschwungen, als wollte er Eindruck schinden!\"  2. \"Kaum ging’s los, zog der Dillo das Messer und wedelte damit, als wär er hart!\"  3. \"Dieser Wappler hat direkt das Messer gezückt und rumgefuchtelt - auf dicke Hose!\""}]'::jsonb, ''),
  ('ea-hod-wueued-mit-de-haend-gfuchtld-owa-kaana-hod-eam-gseeng', 'Ea hod wüüd mit de Händ gfuchtld, owa kaana hod eam gseeng!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Er hat wild mit den Händen gefuchtelt, aber keiner hat ihn gesehen!', '[{"kategorie": "wörtlich", "text": "\"Er hat wild mit den Händen herumgerudert, aber keiner hat ihn gesehen!\"  2. \"Er hat wild herumgestikuliert, aber keiner hat''s gemerkt!\"  3. \"Er hat wie wild mit den Armen gewedelt – doch keiner nahm Notiz!\""}]'::jsonb, ''),
  ('hea-auf-zum-umanaundfuchtln', 'Hea auf zum Umanaundfuchtln!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Hör auf zum Herumfuchteln!', '[{"kategorie": "wörtlich", "text": "\"Lass das Gefuchtel!\"  2. Hör auf, mit den Armen wild herumzugestikulieren!  3. Hör auf, wie ein Verrückter mit den Armen herumzuwedeln!"}]'::jsonb, ''),
  ('hea-auf-zum-umadumfuchtln', 'Hea auf zum Umadumfuchtln!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Hör auf zum Rumfuchteln!', '[{"kategorie": "wörtlich", "text": "\"Lass das Gefuchtel!\"  2. Hör auf, mit den Armen wild herumzugestikulieren!  3. Hör auf, wie ein Verrückter mit den Armen herumzurudern!"}]'::jsonb, ''),
